ss_ar'=>'العنوان بالعربية','address_en'=>'العنوان بالإنكليزية'] as $k=>$label)afield($k,$label,setting($k),true,$k==='address_ar'?'rtl':'ltr');?></div><?php afield('social_links','الروابط الاجتماعية — كل سطر: الاسم | https://...',implode("\n",array_map(fn($s)=>$s['label'].' | '.$s['url'],setting('social_links',[]))),true,'ltr');?></div><div class="admin-card"><h2>ملاحظات داخلية قبل النشر</h2><?php afield('privacy_retention_note','مدة الاحتفاظ / ما يلزم مراجعته (داخلي فقط)',setting('privacy_retention_note'),true);?><p class="admin-hint">لتغيير سياسة الخصوصية المعروضة، حرر صفحة «الخصوصية» بالعربية والإنكليزية. لا يؤدي هذا الحقل الداخلي إلى حذف تلقائي للرسائل.</p></div><div class="admin-actions sticky"><button class="button">حفظ الإعدادات</button><a class="text-link" href="/ar/" target="_blank" rel="noopener">عرض الموقع ↗</a></div></form>
